/** Compose colour scheme for a role set. Pure black is a dark scheme with black base surfaces. */
fun CroftColorRoles.toColorScheme(mode: CroftMode): ColorScheme =
    if (mode == CroftMode.LIGHT) toLightColorScheme() else toDarkColorScheme()

fun croftColorScheme(
    preset: CroftPreset = CroftPreset.DEFAULT,
    mode: CroftMode = CroftMode.LIGHT,
    contrast: CroftContrast = CroftContrast.STANDARD,
): ColorScheme = CroftSchemes.roles(preset, mode, contrast).toColorScheme(mode)

/** A spring from tokens.json: stiffness and damping ratio, as Compose `spring` takes them. */
class CroftSpring(val stiffness: Float, val dampingRatio: Float) {
    fun <T> spec(): FiniteAnimationSpec<T> = spring(dampingRatio = dampingRatio, stiffness = stiffness)
}

object CroftMotion {
    val spatialFast = CroftSpring(CroftTokens.Motion.Spatial.Fast.stiffness.toFloat(), CroftTokens.Motion.Spatial.Fast.damping.toFloat())
    val spatialDefault = CroftSpring(CroftTokens.Motion.Spatial.Default.stiffness.toFloat(), CroftTokens.Motion.Spatial.Default.damping.toFloat())
    val spatialSlow = CroftSpring(CroftTokens.Motion.Spatial.Slow.stiffness.toFloat(), CroftTokens.Motion.Spatial.Slow.damping.toFloat())
    val effectsFast = CroftSpring(CroftTokens.Motion.Effects.Fast.stiffness.toFloat(), CroftTokens.Motion.Effects.Fast.damping.toFloat())
    val effectsDefault = CroftSpring(CroftTokens.Motion.Effects.Default.stiffness.toFloat(), CroftTokens.Motion.Effects.Default.damping.toFloat())
    val effectsSlow = CroftSpring(CroftTokens.Motion.Effects.Slow.stiffness.toFloat(), CroftTokens.Motion.Effects.Slow.damping.toFloat())
    val reducedSpatialFast = CroftSpring(CroftTokens.Motion.StandardSpatialForReducedMotion.Fast.stiffness.toFloat(), CroftTokens.Motion.StandardSpatialForReducedMotion.Fast.damping.toFloat())
    val reducedSpatialDefault = CroftSpring(CroftTokens.Motion.StandardSpatialForReducedMotion.Default.stiffness.toFloat(), CroftTokens.Motion.StandardSpatialForReducedMotion.Default.damping.toFloat())
    val reducedSpatialSlow = CroftSpring(CroftTokens.Motion.StandardSpatialForReducedMotion.Slow.stiffness.toFloat(), CroftTokens.Motion.StandardSpatialForReducedMotion.Slow.damping.toFloat())
}

private class CroftMotionScheme(reducedMotion: Boolean) : MotionScheme {
    private val spatialFast = if (reducedMotion) CroftMotion.reducedSpatialFast else CroftMotion.spatialFast
    private val spatialDefault = if (reducedMotion) CroftMotion.reducedSpatialDefault else CroftMotion.spatialDefault
    private val spatialSlow = if (reducedMotion) CroftMotion.reducedSpatialSlow else CroftMotion.spatialSlow

    override fun <T> defaultSpatialSpec(): FiniteAnimationSpec<T> = spatialDefault.spec()
    override fun <T> fastSpatialSpec(): FiniteAnimationSpec<T> = spatialFast.spec()
    override fun <T> slowSpatialSpec(): FiniteAnimationSpec<T> = spatialSlow.spec()
    override fun <T> defaultEffectsSpec(): FiniteAnimationSpec<T> = CroftMotion.effectsDefault.spec()
    override fun <T> fastEffectsSpec(): FiniteAnimationSpec<T> = CroftMotion.effectsFast.spec()
    override fun <T> slowEffectsSpec(): FiniteAnimationSpec<T> = CroftMotion.effectsSlow.spec()
}

private val CroftExpressiveMotionScheme: MotionScheme = CroftMotionScheme(reducedMotion = false)
private val CroftReducedMotionScheme: MotionScheme = CroftMotionScheme(reducedMotion = true)

/** Pass to `MaterialTheme(motionScheme = ...)`. Reduced swaps in the standard spatial springs (docs/ux/motion.md). */
fun croftMotionScheme(reducedMotion: Boolean = false): MotionScheme =
    if (reducedMotion) CroftReducedMotionScheme else CroftExpressiveMotionScheme
